import httpx

SERVICES = {
    'retrieval': 'http://svc1:8001/health',
    'llm': 'http://svc2:8002/health'
}

def check_service(name, url):
    try:
        r = httpx.get(url, timeout=5.0)
        return 'healthy' if r.status_code == 200 else 'error'
    except Exception:
        return 'unreachable'

@app.get('/health')
def health():
    statuses = {name: check_service(name, url) for name, url in SERVICES.items()}
    all_ok = all(s == 'healthy' for s in statuses.values())
    return {'status': 'healthy' if all_ok else 'degraded', 'services': statuses}

